/* Session-first workout flow layered onto the original single-page app. */
const EXERCISE_EQUIPMENT = {
  'Barbell Bench Press':'Barbell','Incline Barbell Press':'Barbell','Decline Barbell Bench Press':'Barbell','Paused Bench Press':'Barbell','Front Squat':'Barbell','High-Bar Back Squat':'Barbell','Romanian Deadlift':'Barbell','Good Morning':'Barbell','Barbell Hip Thrust':'Barbell','Barbell Curl':'Barbell','Chest-Supported T-Bar Row':'Barbell','Barbell':'Barbell',
  'Dumbbell Bench Press':'Dumbbell','Incline Dumbbell Press':'Dumbbell','Decline Dumbbell Press':'Dumbbell','Goblet Squat':'Dumbbell','Dumbbell Curl':'Dumbbell','Standing Dumbbell Shrugs':'Dumbbell','Incline Dumbbell Shrugs':'Dumbbell','Chest-Supported Dumbbell Row':'Dumbbell','Chest-Supported Dumbbell High Row':'Dumbbell','Dumbbell Lat Pullover':'Dumbbell',
  'Machine Lat Pulldown':'Machine','Lat Pulldown':'Machine','Assisted Pull-Up':'Machine','Machine High Row':'Machine','Machine Chest Press':'Machine','Leg Press':'Machine','Seated Leg Curl':'Machine','Standing Calf Raise':'Machine','Seated Calf Raise':'Machine','Reverse Pec Deck':'Machine','Cable':'Cable','Cable Curl':'Cable','Cable Pushdown':'Cable','Cable Crunch':'Cable','Cable Lateral Raise':'Cable','Cable Rear Delt Fly':'Cable','V-Bar Cable Row':'Cable','Single-Arm Cable Row':'Cable'
};
const EXERCISE_MUSCLE_HINTS = {
  'Barbell Bench Press':'Mid Chest','Incline':'Upper Chest','Decline':'Lower Chest','Chest Press':'Mid Chest','Chest Dip':'Lower Chest','Push-Up':'Upper Chest',
  'Lat Pulldown':'Lats & Upper Back','Pull-Up':'Lats & Upper Back','Row':'Lats & Mid Back','Shrug':'Traps','Rear Delt':'Rear Delts','Reverse Fly':'Rear Delts','Pec Deck':'Rear Delts',
  'Lateral Raise':'Side Delts','Shoulder':'Side Delts','Curl':'Biceps','Biceps':'Biceps','Triceps':'Triceps','Pushdown':'Triceps','Extension':'Triceps','Dip':'Triceps',
  'Squat':'Quads','Leg Press':'Quads','Leg Extension':'Quads','Hamstring':'Hamstrings','Romanian Deadlift':'Hamstrings','Good Morning':'Hamstrings','Nordic':'Hamstrings','Glute':'Glutes','Hip Thrust':'Glutes','Calf':'Calves','Abs':'Abs','Crunch':'Abs','Hanging':'Abs','Dead Bug':'Abs'
};
const BASE_EX_DATA=exData;
function customExerciseRows(){return (state.customExercises||[]).map(e=>({...e,level:'Custom',i:0}))}
exData=function(){return [...BASE_EX_DATA(),...customExerciseRows()]};
function exMeta(name){return exData().find(x=>x.name===name)||{name,muscle:'Other',group:'Custom',level:'Custom',i:0}}
function dateKey(d=new Date()){let x=new Date(d);x.setHours(12,0,0,0);return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`}
function lastExerciseLog(name){return state.logs.filter(l=>l.exercise===name).sort((a,b)=>(b.date||'').localeCompare(a.date||''))[0]}
function getSetRows(log){if(Array.isArray(log?.setDetails)&&log.setDetails.length)return log.setDetails;return Array.from({length:Math.max(1,Number(log?.sets)||1)},()=>({type:'working',weight:Number(log?.weight)||0,reps:Number(log?.reps)||8,complete:true}))}
function appRoutines(){if(!Array.isArray(state.routines))state.routines=[];return state.routines}
function sessionExercises(day){return (day?.exercises||[]).map((x,i)=>{let last=lastExerciseLog(x.name),old=getSetRows(last);return {...x,id:x.id||`ex-${i}`,sets:Array.from({length:Math.max(1,Number(x.sets)||3)},(_,j)=>{let prev=old[j]||old[old.length-1]||{};return {type:prev.type||'working',weight:Number(prev.weight??last?.weight)||0,reps:Number(prev.reps??x.reps)||8,complete:false,rpe:'',notes:''}})}})}
function saveLocal(){try{let key=authUser?'gym-progress-v1:'+authUser.id:'gym-progress-v1';localStorage.setItem(key,JSON.stringify(state))}catch(e){console.warn('Could not save workout cache',e)}}
function saveSessionDraft(){if(state.activeSession){state.activeSession.updatedAt=new Date().toISOString();saveLocal();if(authUser&&cloudReady)void syncSettings()}}
function dayToRoutine(day,index,split){let title=`${day[1]}${/rest/i.test(day[1])?'':' · '+day[0]}`,focus=day[2]||'',all=exData();let muscles=all.filter(x=>{let f=(focus+' '+day[1]).toLowerCase();return f.includes(x.group.toLowerCase())||f.includes(x.muscle.toLowerCase())||(/push/.test(f)&&['Chest','Shoulders','Arms'].includes(x.group))||(/pull/.test(f)&&['Back','Arms'].includes(x.group))||(/legs|lower/.test(f)&&x.group==='Legs')||(/upper/.test(f)&&['Back','Chest','Shoulders','Arms'].includes(x.group))||(/full body/.test(f)&&['Back','Chest','Legs','Arms'].includes(x.group))});let used=new Set(),items=[];for(let x of muscles){let key=x.muscle;if(used.has(key))continue;used.add(key);items.push({name:x.name,muscle:x.muscle,group:x.group,sets:3,reps:'8–12',rest:90,notes:''});if(items.length>=8)break}return {id:crypto.randomUUID(),name:title,day:day[0]||`Day ${index+1}`,focus,rest:/rest/i.test(day[1]),exercises:items}}
function ensureRoutine(){let routines=appRoutines();if(!routines.length){let source=state.split==='Custom'&&Array.isArray(state.custom)?state.custom:(plans[state.split]||plans.PPL);routines.push({id:crypto.randomUUID(),name:state.split||'PPL',days:source.map(dayToRoutine)});saveLocal();if(authUser&&cloudReady)void syncSettings()}return routines}
function currentRoutine(){return ensureRoutine().find(r=>r.id===state.activeRoutineId)||ensureRoutine()[0]}
function routineDayForPlan(index){let r=currentRoutine(),plan=getPlan(),d=plan[index];return r.days.find(x=>x.day===d?.[0]&&x.name.toLowerCase().startsWith(d?.[1]?.toLowerCase()))||r.days.find(x=>x.day===d?.[0]&&!x.rest)||r.days[index]}
function routineMarkup(r){return `<div class="routine-grid">${r.days.map((d,i)=>`<article class="routine-card"><div class="routine-head"><div><span class="eyebrow">${esc(d.day||`Day ${i+1}`)}</span><h3>${esc(d.name)}</h3></div><span class="tag">${d.rest?'REST':`${d.exercises?.length||0} EXERCISES`}</span></div><p class="muted">${esc(d.focus||'Build a focused session')}</p>${d.rest?'<span class="muted">Recovery day</span>':`<button class="primary lime" onclick="startSession('${r.id}','${d.id}')">Start workout →</button> <button class="secondary" onclick="editRoutine('${r.id}')">Edit</button>`}</article>`).join('')}</div>`}
function renderPlan(){let routines=ensureRoutine(),active=currentRoutine(),idx=todayIdx(),today=active.days.find(d=>d.day===dayNames[(new Date().getDay())])||active.days[idx]||active.days[0];let cards=routines.map(r=>`<button class="split-card ${r.id===active.id?'active':''}" onclick="selectRoutine('${r.id}')"><div class="emoji">✳</div><strong>${esc(r.name)}</strong><p>${r.days.filter(d=>!d.rest).length} workout days · ${r.days.reduce((n,d)=>n+(d.exercises?.length||0),0)} planned exercises</p></button>`).join('');return shell(`<div class="hero"><section class="hero-copy"><div class="eyebrow">YOUR WORKOUT, READY TO LOG</div><h1>Beat your last session.<br>One set at a time.</h1><p>Previous weights and reps are ready for you. Start a routine, complete each set and your progress saves as you go.</p>${today&&!today.rest?`<button class="primary lime" onclick="startSession('${active.id}','${today.id}')">Start today’s ${esc(today.name)} →</button>`:'<button class="primary lime" onclick="tab=\'Routines\';render()">Choose a routine →</button>'}</section><section class="today-card"><div class="today-head"><span class="eyebrow">ACTIVE ROUTINE</span><span class="badge">${esc(active.name)}</span></div><div><h2>${esc(today?.name||'Plan your week')}</h2><p>${today?.rest?'Recovery is part of progress':`${today?.exercises?.length||0} exercises · last session prefilled`}</p></div><div class="today-bottom"><span>${state.logs.length} exercise entries</span><button onclick="tab='Routines';render()">Manage →</button></div></section></div>${statsBar()}<section class="card"><div class="section-head"><div><div class="eyebrow">YOUR TRAINING PLAN</div><h2>${esc(active.name)} · Week</h2><p>Tap a workout day to see its routine or start logging.</p></div><button class="primary lime" onclick="createRoutine()">＋ New routine</button></div>${routineMarkup(active)}</section><div class="section-head"><div><div class="eyebrow">SAVED PROGRAMS</div><h2>Routines</h2></div><button class="secondary" onclick="tab='Library';render()">Browse exercises</button></div><div class="split-row">${cards}</div>`)}
function renderWorkout(){let d=view.routineDay;if(!d)return shell('<div class="empty">Choose a routine day to start.</div>');return shell(`<button class="back" onclick="tab='Plan';view={page:'home'};render()">← Routines</button><div class="eyebrow">${esc(d.day)} · ${esc(d.name)}</div><h1>${esc(d.name)} workout</h1><p class="muted">${d.exercises.length} planned exercises. Previous performance appears as you log.</p><div class="workout-categories">${d.exercises.map(e=>`<button class="workout-exercise" onclick="openExercise('${esc(e.name)}')"><strong>${esc(e.name)}</strong><small>${esc(e.muscle)} · ${e.sets} sets × ${esc(e.reps)} reps</small><span class="log-link">See history →</span></button>`).join('')}</div><button class="primary lime" onclick="startSession('${view.routineId}','${d.id}')">Start workout →</button>`)}
function startSession(routineId,dayId){let routine=appRoutines().find(r=>r.id===routineId),day=routine?.days.find(d=>d.id===dayId);if(!day||day.rest){toast('Choose a training day to start.');return}if(state.activeSession&&!confirm('Resume your workout in progress? Choose Cancel to discard it and start this routine.'))state.activeSession=null;if(!state.activeSession)state.activeSession={id:crypto.randomUUID(),routineId,dayId,routineName:routine.name,dayName:day.name,focus:day.focus,date:dateKey(),startedAt:new Date().toISOString(),exercises:sessionExercises(day)};view={page:'session'};tab='Plan';saveLocal();render();window.scrollTo(0,0)}

const _renderProgressWithCalendar=renderProgress;
renderProgress=function(){let html=_renderProgressWithCalendar(),today=new Date(),days=Array.from({length:28},(_,i)=>{let d=new Date(today);d.setDate(d.getDate()-27+i);let key=dateKey(d),logged=state.logs.some(l=>l.date===key);return `<span class="calendar-cell ${logged?'active':''}" title="${key}${logged?' · workout':''}">${d.getDate()}</span>`}).join('');let marker='</div></section><section class="card" style="margin-top:17px"><div class="eyebrow">WEEKLY COMPARISON</div>';return html.replace(marker,`</div></section><section class="card" style="margin-top:17px"><div class="eyebrow">CONSISTENCY CALENDAR</div><h2>Last 4 weeks</h2><div class="consistency-calendar">${days}</div></section><section class="card" style="margin-top:17px"><div class="eyebrow">WEEKLY COMPARISON</div>`)};
statsBar=function(){let days=new Set(state.logs.map(l=>l.date)).size,kg=state.logs.reduce((s,l)=>s+volumeOfLog(l),0);return `<div class="stats"><div class="stat"><strong>${days}</strong><span>Workout days</span></div><div class="stat"><strong>${streak()}</strong><span>Day streak</span></div><div class="stat"><strong>${Math.round(displayWeight(kg)).toLocaleString()}</strong><span>Total kg volume</span></div><div class="stat"><strong>${state.workoutHistory?.length||0}</strong><span>Workouts completed</span></div></div>`};
const calendarCss=document.createElement('style');calendarCss.textContent='.consistency-calendar{display:grid;grid-template-columns:repeat(7,1fr);gap:7px;margin-top:14px}.calendar-cell{display:grid;place-items:center;aspect-ratio:1;border-radius:9px;background:var(--bg);color:var(--muted);font-size:11px}.calendar-cell.active{background:var(--green);color:var(--green-ink);font-weight:800}.template-row{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.metric-picker{display:flex;align-items:center;gap:8px;color:var(--muted);font-size:12px}.metric-picker select{border:1px solid var(--line);border-radius:9px;padding:7px;background:var(--bg);color:var(--ink)}';document.head.append(calendarCss);
const _baseExerciseRow=exerciseRow;
exerciseRow=function(x){let html=_baseExerciseRow(x),equipment=x.equipment||EXERCISE_EQUIPMENT[x.name]||'Free weights / machine';return html.replace(`<small>${x.muscle} · ${x.group}</small>`,`<small>${esc(x.muscle)} · ${esc(x.group)} · ${esc(equipment)}</small>`)};
const _previousOpenExercise=openExercise;
openExercise=function(name){let origin={...view};_previousOpenExercise(name);view.returnContext=origin;render()};
const _previousRenderExercise=renderExercise;
renderExercise=function(){let html=_previousRenderExercise();html=html.replace("view.fromWorkout?openWorkout(view.dayIndex):(view={page:'home'},tab='Library',render())","view.returnContext?.page==='session'?(view={page:'session'},render()):view.fromWorkout?openWorkout(view.dayIndex):(view={page:'home'},tab='Library',render())");html=html.replace('<h2>Weight over time</h2>','<h2>Exercise progress</h2><label class="metric-picker">Chart <select id="exerciseMetric" onchange="drawChart()"><option value="weight">Top weight</option><option value="reps">Best reps</option><option value="volume">Volume</option><option value="oneRM">Estimated 1RM</option></select></label>');return html};
drawChart=function(){let cvs=document.getElementById('chart');if(!cvs)return;let metric=document.getElementById('exerciseMetric')?.value||'weight',logs=getLogsFor(view.name).slice().reverse(),rows=logs.map(l=>{let ss=getSetRows(l).filter(x=>x.type!=='warmup');if(!ss.length)ss=getSetRows(l);let values=ss.map(x=>({weight:Number(x.weight)||0,reps:Number(x.reps)||0}));return {date:l.date,value:metric==='reps'?Math.max(...values.map(x=>x.reps)):metric==='volume'?values.reduce((n,x)=>n+x.weight*x.reps,0):metric==='oneRM'?Math.max(...values.map(x=>x.weight*(1+x.reps/30))):Math.max(...values.map(x=>x.weight))}});let w=cvs.clientWidth||360,h=cvs.clientHeight||210,dpr=devicePixelRatio||1;cvs.width=w*dpr;cvs.height=h*dpr;let c=cvs.getContext('2d');c.scale(dpr,dpr);let style=getComputedStyle(document.body),grid=style.getPropertyValue('--line'),ink=style.getPropertyValue('--muted'),pad={l:42,r:10,t:14,b:28};c.font='11px system-ui';if(!rows.length){c.fillStyle=ink;c.textAlign='center';c.fillText('Finish a workout to see your chart',w/2,h/2);return}let min=Math.min(...rows.map(x=>x.value)),max=Math.max(...rows.map(x=>x.value));if(min===max){min=Math.max(0,min-5);max+=5}let X=i=>pad.l+(rows.length===1?.5:i/(rows.length-1))*(w-pad.l-pad.r),Y=v=>pad.t+(max-v)/(max-min)*(h-pad.t-pad.b);c.strokeStyle=grid;c.fillStyle=ink;c.textAlign='right';for(let i=0;i<4;i++){let v=min+(max-min)*i/3,y=Y(v);c.beginPath();c.moveTo(pad.l,y);c.lineTo(w-pad.r,y);c.stroke();c.fillText(Math.round(v).toString(),pad.l-7,y+4)}c.strokeStyle='#9bd94b';c.lineWidth=3;c.lineJoin='round';c.beginPath();rows.forEach((r,i)=>i?c.lineTo(X(i),Y(r.value)):c.moveTo(X(i),Y(r.value)));c.stroke();rows.forEach((r,i)=>{c.fillStyle='#9bd94b';c.beginPath();c.arc(X(i),Y(r.value),4,0,Math.PI*2);c.fill()});c.textAlign='center';c.fillStyle=ink;[0,rows.length-1].forEach(i=>c.fillText(new Date(rows[i].date+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric'}),X(i),h-5))};
function volumeOfLog(l){let details=getSetRows(l).filter(s=>s.type!=='warmup');return l.setDetails?.length?details.reduce((n,s)=>n+(Number(s.weight)||0)*(Number(s.reps)||0),0):(Number(l.weight)||0)*(Number(l.reps)||0)*(Number(l.sets)||0)}
const _settingsBase=renderSettings;
renderSettings=function(){let html=_settingsBase(),bar=state.unit==='lb'?44:20;return html.replace('<section class="card"><div class="eyebrow">Your data</div>','<section class="card"><div class="eyebrow">GYM TOOL</div><h2>Plate calculator</h2><p class="muted">Find the plates to load on each side of a standard bar.</p><div class="searchbar"><input id="plateTarget" type="number" min="0" step="'+(state.unit==='lb'?'2.5':'1.25')+'" placeholder="Target weight" aria-label="Target weight"><input id="plateBar" type="number" min="0" step="'+(state.unit==='lb'?'2.5':'1.25')+'" value="'+bar+'" aria-label="Bar weight"><button class="secondary" onclick="calculatePlates()">Calculate</button></div><div id="plateResult" class="last-session">Enter target weight.</div></section><section class="card"><div class="eyebrow">Your data</div>')};
function calculatePlates(){let target=Number(document.getElementById('plateTarget').value),bar=Number(document.getElementById('plateBar').value),unit=state.unit,perSide=(target-bar)/2,result=document.getElementById('plateResult');if(!target||bar<0){result.textContent='Enter a target and bar weight.';return}if(perSide<0){result.textContent='Target weight is lighter than the bar.';return}let sizes=unit==='lb'?[45,35,25,10,5,2.5]:[25,20,15,10,5,2.5,1.25],left=perSide,plates=[];for(let size of sizes){let count=Math.floor((left+0.001)/size);if(count){plates.push(`${count} × ${size} ${unit}`);left-=count*size}}result.innerHTML=left>0.1?`Each side: ${plates.join(' + ')||'no plates'} · ${Math.round(left*10)/10} ${unit} still needed`:`<strong>Each side:</strong> ${plates.join(' + ')||'no plates'} <span class="muted">· ${unit} plates per side</span>`}
const _shellBase=shell;
shell=function(content){return _shellBase(content).replace('</a> <button class="secondary" onclick="retryCloud()">Retry connection</button>','</a> <a href="supabase/workout-upgrade.sql" download>Download workout update SQL</a> <button class="secondary" onclick="retryCloud()">Retry connection</button>')};
function setSessionField(ei,si,key,value){let set=state.activeSession?.exercises?.[ei]?.sets?.[si];if(!set)return;set[key]=key==='weight'?Math.max(0,Number(value)||0):key==='reps'?Math.max(0,parseInt(value)||0):value;saveSessionDraft()}
function duplicateSessionSet(ei,si){let ex=state.activeSession.exercises[ei],s=ex.sets[si];ex.sets.splice(si+1,0,{...s,complete:false,rpe:'',notes:''});saveSessionDraft();render()}
function addSessionSet(ei){let ex=state.activeSession.exercises[ei],last=ex.sets.at(-1)||{type:'working',weight:0,reps:8};ex.sets.push({...last,complete:false,rpe:'',notes:''});saveSessionDraft();render()}
function toggleSetComplete(ei,si){let s=state.activeSession?.exercises?.[ei]?.sets?.[si];if(!s)return;s.complete=!s.complete;saveSessionDraft();if(s.complete)timerStart(timerDuration||state.activeSession.exercises[ei].rest||90);else render()}
function setTimerDuration(seconds){timerDuration=seconds;toast(seconds?`Rest timer set to ${seconds/60} min`:`Using the routine rest time`)}
let timerDuration=0;
timerStart=function(seconds){timerStop();timerSecs=Number(seconds)||timerDuration||90;timerPaused=false;document.getElementById('timer').classList.add('show');tickTimer();timerId=setInterval(()=>{if(!timerPaused){timerSecs--;tickTimer();if(timerSecs<=0){timerStop();toast('Rest complete. Ready for your next set?')}}},1000)};
function renderSession(){let s=state.activeSession;if(!s)return shell('<div class="empty">No workout in progress. Start one from Routines.</div>');let completed=s.exercises.reduce((n,e)=>n+e.sets.filter(x=>x.complete).length,0),total=s.exercises.reduce((n,e)=>n+e.sets.length,0);return shell(`<div class="session-top"><div><button class="back" onclick="minimizeSession()">← Minimize</button><div class="eyebrow">WORKOUT IN PROGRESS · ${esc(s.date)}</div><h1>${esc(s.dayName)}</h1><p class="muted">${completed} of ${total} sets complete · autosaved on this device</p></div><button class="secondary" onclick="finishSession()">Finish workout</button></div><div class="beginner-hint"><span>✦</span><div><strong>Quick guide</strong><br>A rep is one repetition; a set is a group of reps. RPE 7 means you could do about 3 more reps. Build toward your target reps with steady form before adding weight.</div></div><div class="session-tools"><label>Rest timer <select onchange="setTimerDuration(+this.value)"><option value="0" selected>Routine default</option><option value="60">60 seconds</option><option value="90">90 seconds</option><option value="120">2 minutes</option></select></label><span class="muted">Tap “Same as last” to add the previous set in one tap.</span></div>${s.exercises.map((e,ei)=>{let last=lastExerciseLog(e.name);return `<section class="session-exercise"><div class="session-exercise-head"><div><span class="eyebrow">${esc(e.group)} · ${esc(e.muscle)}</span><h2>${esc(e.name)}</h2><p class="muted">Previous: ${last?`${formatWeight(last.weight)} × ${last.reps} × ${last.sets}`:'No previous workout'}</p></div><button class="secondary" onclick="openExercise('${esc(e.name)}')">History</button></div><div class="set-list">${e.sets.map((set,si)=>`<div class="set-row ${set.complete?'set-done':''}"><span class="set-number">${si+1}</span><select aria-label="Set type" value="${set.type}" onchange="setSessionField(${ei},${si},'type',this.value)"><option value="warmup" ${set.type==='warmup'?'selected':''}>Warm-up</option><option value="working" ${set.type==='working'?'selected':''}>Working</option><option value="failure" ${set.type==='failure'?'selected':''}>Failure</option><option value="drop" ${set.type==='drop'?'selected':''}>Drop</option></select><input aria-label="Weight" type="number" min="0" step="${state.unit==='lb'?'1':'0.5'}" value="${displayWeight(set.weight)}" onchange="setSessionField(${ei},${si},'weight',this.value/(state.unit==='lb'?2.2046226218:1))"><span>${state.unit}</span><input aria-label="Reps" type="number" min="0" value="${set.reps}" onchange="setSessionField(${ei},${si},'reps',this.value)"><span>reps</span><input aria-label="RPE optional" type="number" min="1" max="10" step="0.5" placeholder="RPE" value="${esc(set.rpe||'')}" onchange="setSessionField(${ei},${si},'rpe',this.value)"><button class="complete-set" aria-label="Complete set" onclick="toggleSetComplete(${ei},${si})">${set.complete?'✓':'Done'}</button><input class="set-note" aria-label="Set note" placeholder="Optional note" value="${esc(set.notes||'')}" onchange="setSessionField(${ei},${si},'notes',this.value)"><button class="secondary copy-set" onclick="duplicateSessionSet(${ei},${si})">↻ Same as last</button></div>`).join('')}</div><div class="session-actions"><button class="secondary" onclick="addSessionSet(${ei})">＋ Add set</button><button class="secondary" onclick="duplicateSessionSet(${ei},${e.sets.length-1})">↻ Duplicate last set</button></div><div class="field"><label>EXERCISE NOTES</label><input value="${esc(e.notes||'')}" placeholder="Optional notes" onchange="state.activeSession.exercises[${ei}].notes=this.value;saveSessionDraft()"></div></section>`}).join('')}<button class="primary lime finish-wide" onclick="finishSession()">Finish workout · Save ${s.exercises.length} exercises</button>`)}
function minimizeSession(){saveSessionDraft();view={page:'home'};tab='Plan';render();toast('Workout saved. Resume it any time from Plan.')}
function finishSession(){let s=state.activeSession;if(!s)return;let entries=[];for(let e of s.exercises){let done=e.sets.filter(x=>x.complete&&x.reps>0);if(!done.length)continue;let work=done.filter(x=>x.type!=='warmup'),sets=work.length?work:done,weight=Math.max(...sets.map(x=>Number(x.weight)||0)),repAvg=Math.round(sets.reduce((n,x)=>n+(Number(x.reps)||0),0)/sets.length),info=exMeta(e.name);entries.push({id:crypto.randomUUID(),sessionId:s.id,routineName:s.routineName,exercise:e.name,muscle:e.muscle||info.muscle,group:e.group||info.group,weight,reps:repAvg,sets:sets.length,date:s.date,setDetails:done.map(x=>({...x,weight:Number(x.weight)||0,reps:Number(x.reps)||0})),notes:e.notes||''})}if(!entries.length){toast('Complete at least one set before finishing.');return}let oldPRs=entries.filter(e=>e.weight>Math.max(0,...getLogsFor(e.exercise).map(l=>l.weight))).map(e=>e.exercise);state.logs.push(...entries);state.workoutHistory=[...(state.workoutHistory||[]),{id:s.id,date:s.date,name:s.dayName,routine:s.routineName,entries:entries.length,completedAt:new Date().toISOString()}];state.activeSession=null;save();for(let entry of entries)void syncLog(entry);render();timerStop();toast(oldPRs.length?`🏆 New personal record · ${oldPRs.join(', ')}`:`Workout complete · ${entries.length} exercises saved`)}
function selectRoutine(id){state.activeRoutineId=id;save();render()}
function createRoutine(){openRoutineEditor(null)}
function duplicateRoutine(id){let r=appRoutines().find(x=>x.id===id);if(!r)return;let copy=JSON.parse(JSON.stringify(r));copy.id=crypto.randomUUID();copy.name+=' Copy';copy.days.forEach(d=>d.id=crypto.randomUUID());state.routines.push(copy);state.activeRoutineId=copy.id;save();render();toast('Routine duplicated')}
function editRoutine(id){let r=appRoutines().find(x=>x.id===id);openRoutineEditor(r||null)}
function routineDayHtml(d,i){let options=exData().map(x=>`<option value="${esc(x.name)}">${esc(x.name)} · ${esc(x.muscle)}</option>`).join('');return `<div class="routine-edit-day" data-index="${i}"><div class="custom-day"><input class="routine-day-name" value="${esc(d.name||'Workout day')}" placeholder="Day name"><input class="routine-day-focus" value="${esc(d.focus||'')}" placeholder="Focus e.g. chest, triceps"><label><input type="checkbox" class="routine-day-rest" ${d.rest?'checked':''}> Rest</label></div><div class="routine-exercise-edit">${(d.exercises||[]).map((e,j)=>routineExerciseHtml(e,j)).join('')}</div><div class="routine-edit-actions"><select class="routine-add-select">${options}</select><button class="secondary" type="button" onclick="addRoutineExercise(this)">＋ Exercise</button><button class="secondary" type="button" onclick="this.closest('.routine-edit-day').remove()">Remove day</button></div></div>`}
function routineExerciseHtml(e){return `<div class="routine-exercise-edit-row"><strong>${esc(e.name)}</strong><label>Sets <input class="routine-sets" type="number" min="1" max="10" value="${Number(e.sets)||3}"></label><label>Target reps <input class="routine-reps" value="${esc(e.reps||'8–12')}"></label><label>Rest sec <input class="routine-rest" type="number" min="0" value="${Number(e.rest)||90}"></label><input class="routine-notes" placeholder="Exercise note" value="${esc(e.notes||'')}"><button type="button" class="delete" aria-label="Remove exercise" onclick="this.parentElement.remove()">×</button></div>`}
function addRoutineExercise(button){let day=button.closest('.routine-edit-day'),name=day.querySelector('.routine-add-select').value,info=exMeta(name);day.querySelector('.routine-exercise-edit').insertAdjacentHTML('beforeend',routineExerciseHtml({name,muscle:info.muscle,group:info.group,sets:3,reps:'8–12',rest:90,notes:''}))}
function addRoutineDay(){let root=document.getElementById('routineDays'),index=root.children.length,day={id:crypto.randomUUID(),name:`Day ${index+1}`,focus:'',rest:false,exercises:[]};root.insertAdjacentHTML('beforeend',routineDayHtml(day,index))}
function openRoutineEditor(existing){let r=existing?JSON.parse(JSON.stringify(existing)):{id:crypto.randomUUID(),name:'My routine',days:(plans[state.split]||plans.PPL).filter(d=>!/rest/i.test(d[1])).slice(0,5).map(dayToRoutine)};document.getElementById('modal').innerHTML=`<div class="modal routine-modal"><div class="modal-head"><div><div class="eyebrow">MAKE IT YOURS</div><h2>${existing?'Edit routine':'Create routine'}</h2></div><button class="modal-close" onclick="closeModal()">×</button></div><label class="field">ROUTINE NAME<input id="routineName" value="${esc(r.name)}" placeholder="Push / Pull / Legs"></label><div id="routineDays">${r.days.map(routineDayHtml).join('')}</div><button class="secondary" onclick="addRoutineDay()">＋ Add day</button><div class="routine-modal-foot"><button class="secondary" onclick="duplicateRoutine('${r.id}');closeModal()">Duplicate</button>${existing?`<button class="delete" onclick="removeRoutine('${r.id}')">Delete</button>`:''}<button class="primary lime" onclick="saveRoutine('${r.id}')">Save routine</button></div></div>`;document.getElementById('modal').classList.add('show')}
function saveRoutine(id){let days=[...document.querySelectorAll('.routine-edit-day')].map((el,i)=>{let name=el.querySelector('.routine-day-name').value.trim()||`Day ${i+1}`,focus=el.querySelector('.routine-day-focus').value.trim(),rest=el.querySelector('.routine-day-rest').checked,exercises=[...el.querySelectorAll('.routine-exercise-edit-row')].map(row=>{let info=exMeta(row.querySelector('strong').textContent);return {name:info.name,muscle:info.muscle,group:info.group,sets:Number(row.querySelector('.routine-sets').value)||3,reps:row.querySelector('.routine-reps').value||'8–12',rest:Number(row.querySelector('.routine-rest').value)||90,notes:row.querySelector('.routine-notes').value}});return {id:crypto.randomUUID(),day:['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'][i]||`Day ${i+1}`,name,focus,rest,exercises}});if(!days.length){toast('Add at least one workout day');return}if(days.some(d=>!d.rest&&!d.exercises.length)){toast('Add at least one exercise to each training day');return}let r={id,name:document.getElementById('routineName').value.trim()||'My routine',days},ix=appRoutines().findIndex(x=>x.id===id);if(ix<0)state.routines.push(r);else state.routines[ix]=r;state.activeRoutineId=id;save();closeModal();render();toast('Routine saved')}
function removeRoutine(id){if(appRoutines().length<2){toast('Keep at least one routine');return}if(!confirm('Delete this routine? Workout history will remain.'))return;state.routines=appRoutines().filter(x=>x.id!==id);if(state.activeRoutineId===id)state.activeRoutineId=state.routines[0].id;save();closeModal();render()}
function renderSessionHistory(){let hist=[...(state.workoutHistory||[])].sort((a,b)=>b.date.localeCompare(a.date));return `<section class="card" style="margin-top:18px"><div class="eyebrow">COMPLETED WORKOUTS</div><h2>Workout history</h2><div class="records" style="margin-top:12px">${hist.slice(0,12).map(x=>`<div class="record"><div><strong>${esc(x.name)}</strong><br><span>${esc(x.routine)} · ${new Date(x.date+'T12:00:00').toLocaleDateString()} · ${x.entries} exercises</span></div></div>`).join('')||'<div class="empty">Finished workouts will appear here.</div>'}</div></section>`}
function renderProgress(){let logs=state.logs,unique=[...new Set(logs.map(l=>l.date))],date=new Date(),monday=new Date(date);monday.setHours(12,0,0,0);monday.setDate(date.getDate()-((date.getDay()+6)%7));let thisStart=dateKey(monday),prevStart=new Date(monday);prevStart.setDate(prevStart.getDate()-7);let prevKey=dateKey(prevStart),nextWeek=new Date(monday);nextWeek.setDate(nextWeek.getDate()+7);let thisEnd=dateKey(nextWeek),prev=logs.filter(l=>l.date>=prevKey&&l.date<thisStart),curr=logs.filter(l=>l.date>=thisStart&&l.date<thisEnd),vol=a=>a.reduce((n,l)=>n+volumeOfLog(l),0),we=vol(curr),pe=vol(prev),groups={};curr.forEach(l=>groups[l.muscle||'Other']=(groups[l.muscle||'Other']||0)+volumeOfLog(l));let prs={};logs.forEach(l=>{let p=prs[l.exercise]||(prs[l.exercise]={weight:0,bestReps:0,repsWeight:0,oneRM:0});let sets=getSetRows(l).filter(x=>x.type!=='warmup');for(let s of sets){if(Number(s.weight)>p.weight)p.weight=Number(s.weight);if(Number(s.reps)>p.bestReps){p.bestReps=Number(s.reps);p.repsWeight=Number(s.weight)}let est=Number(s.weight)*(1+Number(s.reps)/30);if(est>p.oneRM)p.oneRM=est}});let week=Array.from({length:7},(_,i)=>{let d=new Date(monday);d.setDate(d.getDate()+i);return dateKey(d)});let trending=Object.entries(prs).sort((a,b)=>b[1].oneRM-a[1].oneRM);return shell(`<div class="eyebrow">TRAINING THAT ADDS UP</div><h1>Your progress</h1><p class="muted">Clear feedback from the work you put in.</p><div class="progress-top"><div class="card"><div class="eyebrow">Workout days</div><div class="progress-number">${unique.length}</div><span class="muted">all time</span></div><div class="card"><div class="eyebrow">Day streak</div><div class="progress-number">${streak()} 🔥</div><span class="muted">consecutive days</span></div><div class="card"><div class="eyebrow">Total lifted volume</div><div class="progress-number">${Math.round(displayWeight(vol(logs))).toLocaleString()} <small>${state.unit}</small></div><span class="muted">from exercise summaries</span></div></div><section class="card" style="margin-top:17px"><div class="eyebrow">CONSISTENCY</div><h2>Last 7 days</h2><div class="week-strip">${week.map((d,i)=>`<div class="week-day">${'MTWTFSS'[i]}<b class="${logs.some(l=>l.date===d)?'done':''}">${new Date(d+'T12:00:00').getDate()}</b></div>`).join('')}</div></section><section class="card" style="margin-top:17px"><div class="eyebrow">WEEKLY COMPARISON</div><h2>This week vs last week</h2><div class="comparison-grid"><div><strong>${curr.length}</strong><span>exercise entries this week</span></div><div><strong>${prev.length}</strong><span>exercise entries last week</span></div><div><strong>${Math.round(displayWeight(we)).toLocaleString()} ${state.unit}</strong><span>estimated volume this week</span></div><div><strong>${we>=pe?'+':'−'}${pe?Math.round(Math.abs(we-pe)/pe*100):100}%</strong><span>volume vs previous week</span></div></div></section><section class="card" style="margin-top:17px"><div class="eyebrow">MUSCLE VOLUME</div><h2>This week by muscle</h2><p class="muted">Estimated tonnage · converted to your selected unit.</p><div class="records" style="margin-top:12px">${Object.entries(groups).sort((a,b)=>b[1]-a[1]).map(([m,v])=>`<div class="record"><strong>${esc(m)}</strong><strong>${Math.round(displayWeight(v)).toLocaleString()} ${state.unit}</strong></div>`).join('')||'<div class="empty">Finish a workout this week to see muscle volume.</div>'}</div></section><section class="card" style="margin-top:17px"><div class="eyebrow">PERSONAL RECORDS</div><h2>Top lifts</h2><div class="records" style="margin-top:12px">${trending.slice(0,12).map(([n,p])=>`<button class="record pr-link" onclick="openExercise('${esc(n)}')"><div><strong>${esc(n)}</strong><br><span>Heaviest ${formatWeight(p.weight)} · Best ${p.bestReps} reps @ ${formatWeight(p.repsWeight)} · Est. 1RM ${formatWeight(p.oneRM)}</span></div><span>›</span></button>`).join('')||'<div class="empty">Complete your first workout to build your records.</div>'}</div></section>${renderSessionHistory()}`)}
function renderSettings(){return shell(`<div class="eyebrow">MAKE IT YOURS</div><h1>Settings</h1><p class="muted">Private by default. Your workout drafts save on this device and sync when connected.</p><div class="layout"><section class="card"><div class="eyebrow">Appearance</div><h2>Theme</h2><div class="searchbar"><button class="secondary" onclick="setTheme('system')">Device</button><button class="secondary" onclick="setTheme('light')">☀ Light</button><button class="secondary" onclick="setTheme('dark')">☾ Dark</button></div></section><section class="card"><div class="eyebrow">Training preferences</div><h2>Weight units</h2><p class="muted">Weights are stored accurately in kg and displayed in your chosen unit.</p><div class="searchbar"><button class="secondary" onclick="setUnit('kg')">${state.unit==='kg'?'✓ ':''}Kilograms (kg)</button><button class="secondary" onclick="setUnit('lb')">${state.unit==='lb'?'✓ ':''}Pounds (lb)</button></div></section><section class="card"><div class="eyebrow">Offline and privacy</div><h2>App installed and data control</h2><p class="muted">Your exercise list and app shell can work offline after the first visit. Workout data stays on your device until cloud sync is available.</p><button class="secondary" onclick="installApp()">＋ Add to Home Screen</button></section><section class="card"><div class="eyebrow">Your data</div><h2>${state.logs.length} saved exercise entries</h2><p class="muted">Export or restore a backup any time.</p><button class="secondary" onclick="exportData()">Download backup</button> <button class="secondary" onclick="exportCSV()">Export workouts CSV</button> <button class="secondary" onclick="document.getElementById('importFile').click()">Restore backup</button><input id="importFile" type="file" accept="application/json" hidden onchange="importData(event)"></section></div>`)}
render=function(){let app=document.getElementById('app');try{document.documentElement.dataset.theme=state.theme;if(authLoading)app.innerHTML='<div class="auth-shell"><section class="auth-card"><div class="logo">✳</div><h1>Connecting your account…</h1><p class="muted">This should only take a moment.</p></section></div>';else if(!authUser)app.innerHTML=renderAuth();else if(view.page==='session')app.innerHTML=renderSession();else if(view.page==='exercise')app.innerHTML=renderExercise();else if(view.page==='workout')app.innerHTML=renderWorkout();else if(tab==='Plan')app.innerHTML=renderPlan();else if(tab==='Library')app.innerHTML=renderLibrary();else if(tab==='Progress')app.innerHTML=renderProgress();else app.innerHTML=renderSettings()}catch(error){authLoading=false;cloudReady=false;cloudError='The workout screen could not load: '+(error?.message||'unexpected app error');app.innerHTML='<div class="auth-shell"><section class="auth-card"><div class="eyebrow">GYM PROGRESS</div><h1>We hit a snag</h1><p class="auth-feedback error">'+esc(cloudError)+'</p><button class="primary lime" onclick="view={page:\'home\'};tab=\'Plan\';render()">Back to your plan</button></section></div>'}renderTabs();if(view.page==='exercise'&&authUser)drawChart()};
renderTabs=function(){document.getElementById('tabs').innerHTML=authUser?['Plan','Routines','Library','Progress','Settings'].map((t,i)=>`<button class="tab ${tab===t?'active':''}" onclick="tab='${t}';view={page:'home'};render()">${['▦','≡','⌕','↗','⚙'][i]} &nbsp;${t}</button>`).join(''):''};
