function importData(e){let f=e.target.files[0];if(!f)return;let r=new FileReader();r.onload=()=>{try{let x=JSON.parse(r.result);if(!Array.isArray(x.logs))throw 0;state={...state,...x};ensureRoutine();save();render();toast('Backup restored')}catch{toast('That backup file could not be read')}};r.readAsText(f)}
function installApp(){if(window.__installPrompt){window.__installPrompt.prompt();window.__installPrompt.userChoice.then(()=>window.__installPrompt=null);return}toast('Use your browser menu and choose “Install app” or “Add to Home Screen”.')}
