const enhancementCss=document.createElement('style');enhancementCss.textContent=`.routine-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin:16px 0}.routine-card,.session-exercise{background:var(--surface);border:1px solid var(--line);border-radius:18px;padding:17px;margin:12px 0}.routine-head,.session-exercise-head,.session-top{display:flex;justify-content:space-between;align-items:flex-start;gap:12px}.routine-head h3{margin-top:4px}.routine-edit-day{border:1px solid var(--line);border-radius:15px;padding:13px;margin:12px 0}.routine-edit-day .custom-day{grid-template-columns:1fr 1fr auto}.routine-edit-actions,.routine-modal-foot,.session-actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:10px 0}.routine-exercise-edit-row{display:grid;grid-template-columns:minmax(110px,1.4fr) repeat(3,minmax(52px,.5fr)) minmax(90px,1fr) auto;gap:7px;align-items:center;padding:9px 0;border-bottom:1px solid var(--line)}.routine-exercise-edit-row label{font-size:10px;color:var(--muted)}.routine-exercise-edit-row input,.routine-edit-day input,.routine-edit-day select,.set-row input,.set-row select,.session-tools select{min-width:0;width:100%;padding:8px;border:1px solid var(--line);border-radius:9px;background:var(--bg);color:var(--ink)}.routine-modal{width:min(900px,100%)}.routine-modal-foot{justify-content:flex-end;margin-top:16px}.session-tools{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;background:var(--soft);padding:12px 15px;border-radius:14px;margin:15px 0}.session-tools label{display:flex;align-items:center;gap:8px;font-weight:700;font-size:13px}.set-list{display:grid;gap:8px;margin:14px 0}.set-row{display:grid;grid-template-columns:30px 100px minmax(55px,1fr) 25px minmax(48px,.7fr) 30px 70px 60px;gap:7px;align-items:center;padding:8px;background:var(--bg);border:1px solid var(--line);border-radius:13px}.set-row.set-done{background:var(--soft);border-color:#9bd94b}.set-number{font-weight:800;text-align:center}.complete-set{border:0;border-radius:9px;background:var(--green);padding:9px 6px;font-weight:800;color:var(--green-ink)}.set-note{grid-column:2/6}.copy-set{font-size:10px;padding:7px 5px}.finish-wide{width:100%;margin:15px 0 25px}.comparison-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-top:14px}.comparison-grid>div{padding:13px;background:var(--bg);border-radius:13px}.comparison-grid strong,.comparison-grid span{display:block}.comparison-grid strong{font-size:20px}.comparison-grid span{font-size:11px;color:var(--muted)}.pr-link{width:100%;text-align:left;background:var(--surface);color:var(--ink);cursor:pointer}.tabs .tab{padding-left:12px;padding-right:12px}.session-top{align-items:center}.field input[type=checkbox]{width:auto}@media(max-width:700px){.routine-grid{grid-template-columns:1fr}.routine-exercise-edit-row{grid-template-columns:1fr 1fr 1fr;gap:8px}.routine-exercise-edit-row strong{grid-column:1/-1}.routine-exercise-edit-row .routine-notes{grid-column:1/3}.set-row{grid-template-columns:24px 78px minmax(45px,1fr) 19px minmax(42px,.7fr) 26px 62px;gap:5px;padding:6px}.set-row .set-note{grid-column:2/5}.set-row .copy-set{grid-column:5/8}.set-row input,.set-row select{padding:7px 4px;font-size:12px}.comparison-grid{grid-template-columns:repeat(2,1fr)}.routine-modal{padding:16px}.session-exercise{padding:13px}.session-exercise-head{align-items:center}.session-top{align-items:flex-start}.tabs{overflow-x:auto;justify-content:flex-start}.tab{white-space:nowrap}.routine-edit-day .custom-day{grid-template-columns:1fr 1fr}.routine-edit-day .custom-day label{grid-column:1/-1}}`;document.head.append(enhancementCss);
render=function(){let app=document.getElementById('app');try{document.documentElement.dataset.theme=state.theme;if(authLoading)app.innerHTML='<div class="auth-shell"><section class="auth-card"><div class="logo">✳</div><h1>Connecting your account…</h1><p class="muted">This should only take a moment.</p></section></div>';else if(!authUser)app.innerHTML=renderAuth();else if(view.page==='session')app.innerHTML=renderSession();else if(view.page==='exercise')app.innerHTML=renderExercise();else if(view.page==='workout')app.innerHTML=renderWorkout();else if(tab==='Plan')app.innerHTML=renderPlan();else if(tab==='Routines')app.innerHTML=renderRoutines();else if(tab==='Library')app.innerHTML=renderLibrary();else if(tab==='Progress')app.innerHTML=renderProgress();else app.innerHTML=renderSettings()}catch(error){authLoading=false;cloudReady=false;cloudError='The workout screen could not load: '+(error?.message||'unexpected app error');app.innerHTML='<div class="auth-shell"><section class="auth-card"><div class="eyebrow">GYM PROGRESS</div><h1>We hit a snag</h1><p class="auth-feedback error">'+esc(cloudError)+'</p><button class="primary lime" onclick="view={page:\'home\'};tab=\'Plan\';render()">Back to your plan</button></section></div>'}renderTabs();if(view.page==='exercise'&&authUser)drawChart()};
function renderRoutines(){let routines=ensureRoutine();return shell(`<div class="eyebrow">YOUR TRAINING PROGRAMS</div><h1>Routines</h1><p class="muted">Plan your days once, then start each workout with previous performance ready.</p><div class="section-head"><div><h2>Saved routines</h2><p>Change, copy or start any routine day.</p></div><button class="primary lime" onclick="createRoutine()">＋ Create routine</button></div><section class="card"><div class="eyebrow">START WITH A PLAN</div><h2>Quick templates</h2><div class="template-row">${Object.keys(plans).map(name=>`<button class="secondary" onclick="createRoutineFromSplit('${name}')">＋ ${name}</button>`).join('')}</div></section>${routines.map(r=>`<section class="card" style="margin:14px 0"><div class="routine-head"><div><div class="eyebrow">${r.days.filter(d=>!d.rest).length} TRAINING DAYS</div><h2>${esc(r.name)}</h2></div><div><button class="secondary" onclick="editRoutine('${r.id}')">Edit</button> <button class="secondary" onclick="duplicateRoutine('${r.id}')">Duplicate</button></div></div>${routineMarkup(r)}</section>`).join('')}`)}
function createRoutineFromSplit(name){let r={id:crypto.randomUUID(),name,days:plans[name].map(dayToRoutine)};state.routines=[...appRoutines(),r];state.activeRoutineId=r.id;save();render();toast(`${name} routine added`)}
function recommendRoutine(days){let name=days<=3?'Full Body':days===4?'Upper / Lower':days===5?'5-Day Split':'PPL',reason=days<=3?'A few full-body days keep each muscle in your weekly routine.':days===4?'Upper/lower gives you a balanced four-day week.':days===5?'Five days allow focused sessions with recovery days.':'Push/pull/legs suits six training days.';let node=document.getElementById('routine-recommendation');if(node)node.innerHTML=`<p><strong>${name}</strong> · ${reason}</p><button class="primary lime" onclick="createRoutineFromSplit('${name}')">Add ${name} routine</button>`}
const _planBeforeReco=renderPlan;
renderPlan=function(){let html=_planBeforeReco(),addition='<section class="card" style="margin-top:16px"><div class="eyebrow">NOT SURE WHERE TO START?</div><h2>Find a routine that fits</h2><p class="muted">How many days can you train most weeks?</p><div class="field"><select aria-label="Training days per week" onchange="recommendRoutine(+this.value)"><option value="">Choose training days</option><option value="2">2 days</option><option value="3">3 days</option><option value="4">4 days</option><option value="5">5 days</option><option value="6">6 days</option></select></div><div id="routine-recommendation" class="reco"><p>Select the days you can train and get a suggestion.</p></div></section>';return html.replace('<footer>Your progress',addition+'<footer>Your progress')};
function createCustomExercise(){document.getElementById('modal').innerHTML=`<div class="modal"><div class="modal-head"><div><div class="eyebrow">YOUR EXERCISE</div><h2>Add custom exercise</h2></div><button class="modal-close" onclick="closeModal()">×</button></div><form class="auth-form" onsubmit="saveCustomExercise(event)"><label>Exercise name<input id="customExerciseName" required placeholder="e.g. Smith machine squat"></label><label>Muscle group<input id="customExerciseMuscle" required placeholder="e.g. Quads"></label><label>Category<select id="customExerciseGroup">${Object.keys(library).map(g=>`<option>${esc(g)}</option>`).join('')}<option>Custom</option></select></label><label>Equipment<input id="customExerciseEquipment" placeholder="e.g. Smith machine"></label><button class="primary lime">Save exercise</button></form></div>`;document.getElementById('modal').classList.add('show')}
function saveCustomExercise(e){e.preventDefault();let name=document.getElementById('customExerciseName').value.trim();if(exData().some(x=>x.name.toLowerCase()===name.toLowerCase())){toast('That exercise is already in the library');return}let group=document.getElementById('customExerciseGroup').value,muscle=document.getElementById('customExerciseMuscle').value.trim(),equipment=document.getElementById('customExerciseEquipment').value.trim();state.customExercises=[...(state.customExercises||[]),{name,group,muscle,level:'Custom',i:0,equipment}];save();closeModal();render();toast('Custom exercise added to your library')}
const BASE_RENDER_LIBRARY=renderLibrary;
renderLibrary=function(){let html=BASE_RENDER_LIBRARY();return html.replace('<h1>Exercise library</h1>','<h1>Exercise library</h1><button class="secondary" onclick="createCustomExercise()">＋ Add custom exercise</button>')};
const BASE_OPEN_EXERCISE=openExercise;
openExercise=function(name){let origin={...view};BASE_OPEN_EXERCISE(name);view.returnContext=origin};
const BASE_RENDER_EXERCISE2=renderExercise;
renderExercise=function(){let html=BASE_RENDER_EXERCISE2();if(view.returnContext?.page==='session')html=html.replace('view.fromWorkout?openWorkout(view.dayIndex):(view={page:\'home\'},tab=\'Library\',render())',"view={page:'session'};render()");return html};
const BASE_SYNC_SETTINGS=syncSettings;
syncSettings=async function(){if(!authUser||!cloudReady)return;try{let {error}=await withTimeout(supa.from('gym_settings').upsert({user_id:authUser.id,split:state.split,custom_split:state.custom,theme:state.theme,routines:state.routines||[],active_routine_id:state.activeRoutineId||null,workout_history:state.workoutHistory||[],active_session:state.activeSession||null,custom_exercises:state.customExercises||[],updated_at:new Date().toISOString()},{onConflict:'user_id'}),12000,'Cloud sync timed out; your data remains on this device.');if(error)throw error}catch(e){cloudReady=false;cloudError='Your changes are saved on this device. Cloud sync will retry when you reconnect.';render()}};
const BASE_SYNC_LOG=syncLog;
syncLog=async function(entry){if(!authUser||!cloudReady){entry.pendingSync=true;saveLocal();return}try{let row={id:entry.id,user_id:authUser.id,exercise:entry.exercise,muscle:entry.muscle||'Unknown',exercise_group:entry.group||'Unknown',weight:entry.weight,reps:entry.reps,sets:entry.sets,logged_on:entry.date,session_id:entry.sessionId||null,routine_name:entry.routineName||null,set_details:entry.setDetails||[],notes:entry.notes||''};let {error}=await withTimeout(supa.from('exercise_logs').upsert(row,{onConflict:'id'}),12000,'Workout saved on this device; cloud sync timed out.');if(error)throw error;entry.pendingSync=false;saveLocal()}catch(e){entry.pendingSync=true;cloudReady=false;cloudError='Workout saved on this device. Cloud sync will retry when you reconnect.';saveLocal();render()}};
const BASE_LOAD_ACCOUNT=loadAccountData;
loadAccountData=async function(user){await BASE_LOAD_ACCOUNT(user);if(!authUser)return;try{let {data,error}=await supa.from('gym_settings').select('routines,active_routine_id,workout_history,active_session,custom_exercises').eq('user_id',user.id).maybeSingle();if(error)throw error;if(data){state.routines=data.routines||state.routines||[];state.activeRoutineId=data.active_routine_id||state.activeRoutineId;state.workoutHistory=data.workout_history||state.workoutHistory||[];state.activeSession=data.active_session||state.activeSession;state.customExercises=data.custom_exercises||state.customExercises||[]}let {data:logs,error:logError}=await supa.from('exercise_logs').select('id,session_id,routine_name,set_details,notes').eq('user_id',user.id);if(logError)throw logError;let extras=new Map((logs||[]).map(x=>[x.id,x]));state.logs=state.logs.map(l=>{let x=extras.get(l.id);return x?{...l,sessionId:x.session_id,routineName:x.routine_name,setDetails:x.set_details||[],notes:x.notes||''}:l});ensureRoutine();saveLocal();render()}catch(e){cloudReady=false;cloudError='Run the workout data update in supabase/workout-upgrade.sql to sync routines and set notes.';render()}};
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&state.activeSession)saveSessionDraft()});
function startSession(routineId,dayId){let routine=appRoutines().find(r=>r.id===routineId),day=routine?.days.find(d=>d.id===dayId);if(!day||day.rest){toast('Choose a training day to start.');return}if(state.activeSession&&!confirm('Resume your workout in progress? Choose Cancel to discard it and start this routine.'))state.activeSession=null;if(!state.activeSession)state.activeSession={id:crypto.randomUUID(),routineId,dayId,routineName:routine.name,dayName:day.name,focus:day.focus,date:dateKey(),startedAt:new Date().toISOString(),exercises:sessionExercises(day)};view={page:'session'};tab='Plan';saveLocal();render();window.scrollTo(0,0)}
if(!authLoading)render();
